#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
#include <cstdint>
static volatile std::uint64_t sink;
using Tr=BinaryTrie<unsigned,29>;
using Clock=std::chrono::steady_clock;
using Nanoseconds=std::chrono::nanoseconds;
static std::uint64_t elapsed(Clock::time_point t){return std::chrono::duration_cast<Nanoseconds>(Clock::now()-t).count();}
static unsigned key(std::size_t i){return static_cast<unsigned>((i*2654435761u)&((1u<<30)-1));}
static void run(std::size_t d,bool ids,int mode){
 const int rounds=mode==1?1:(d==1?2000:d==32?300:1);
 const std::size_t ops=mode==1?200000:d;
 std::uint64_t add_ns=0,del_ns=0,total=0;
 for(int round=0;round<rounds;++round){
  Tr tr;
  if(mode!=0){for(std::size_t i=0;i<d;++i)tr.add(key(i),ids?5:-1);}
  if(mode==2){for(std::size_t i=0;i<d;++i)if(!tr.del(key(i),ids?5:-1))std::abort();}
  asm volatile("" ::: "memory");
  auto start=Clock::now();
  for(std::size_t i=0;i<ops;++i)tr.add(key(i%d),ids?9:-1);
  add_ns+=elapsed(start);
  total+=tr.size();
  asm volatile("" ::: "memory");
  start=Clock::now();
  for(std::size_t i=0;i<ops;++i)if(!tr.del(key(i%d),ids?9:-1))std::abort();
  del_ns+=elapsed(start);
  total+=tr.size();
 }
 sink=total;
 const char*name=mode==0?"new":mode==1?"duplicate":"reuse";
 std::printf("D%zu/%s/%s/add,%.6f,%llu\n",d,name,ids?"IDs":"anon",double(add_ns)/(ops*rounds),(unsigned long long)total);
 std::printf("D%zu/%s/%s/del,%.6f,%llu\n",d,name,ids?"IDs":"anon",double(del_ns)/(ops*rounds),(unsigned long long)total);
}
int main(){std::puts("case,ns_per_op,checksum");for(std::size_t d:{std::size_t{1},std::size_t{32},std::size_t{100000}})for(bool ids:{false,true})for(int mode:{0,1,2})run(d,ids,mode);}

